'use strict';
const SKILLS=[{id:'S01',area:'IT fundamentals',name:'Web addresses',icon:'globe'},{id:'S02',area:'Information literacy',name:'Checking online claims',icon:'search'},{id:'S03',area:'Digital safety',name:'Recognising phishing',icon:'shield'},{id:'S04',area:'Digital productivity',name:'Spreadsheet basics',icon:'grid'}];
const CATALOG=[
 {id:'A01',title:'Understand a web address',skill:'S01',difficulty:1,prereq:[],order:1,minutes:5,status:'Published',version:1,objective:'Identify who controls a website by reading its address.'},
 {id:'A02',title:'Check the source of an online claim',skill:'S02',difficulty:1,prereq:[],order:2,minutes:6,status:'Published',version:1,objective:'Find the original source behind a claim and check what it actually says.'},
 {id:'A03',title:'Spot phishing warning signs',skill:'S03',difficulty:1,prereq:['S01'],order:3,minutes:7,status:'Published',version:1,objective:'Recognise a suspicious message and choose a safer next step.'},
 {id:'A04',title:'Calculate a spreadsheet total',skill:'S04',difficulty:2,prereq:[],order:4,minutes:6,status:'Published',version:1,objective:'Use a SUM formula and check that its range includes the intended cells.'},
 {id:'A05',title:'Examine links in a suspicious message',skill:'S03',difficulty:2,prereq:['S01'],order:5,minutes:8,status:'Published',version:1,objective:'Compare a link with the claimed sender before deciding how to respond.'},
 {id:'A06',title:'Compare evidence from two sources',skill:'S02',difficulty:2,prereq:[],order:6,minutes:8,status:'Published',version:1,objective:'Compare the author, date, and evidence behind two versions of a claim.'}
];
const Q=(id,skill,prompt,options,correct,why)=>({id,skill,prompt,options,correct,why});
const DIAGNOSTIC=[
 Q('D01','S01','In https://portal.example.edu/courses, which is the registered domain?',['https','portal','example.edu','courses'],2,'The registered domain here is example.edu. “portal” is a subdomain and “courses” is part of the path.'),
 Q('D02','S01','Who controls university-login.example.net in this example?',['The owner of example.net','Any university named in the page title','The user opening the link','The browser company'],0,'The words in a subdomain do not prove affiliation. The registered domain here is example.net.'),
 Q('D03','S02','An AI answer states a surprising fact without a source. What is the strongest next step?',['Share it because it sounds confident','Check the claim against a relevant original source','Ask it to write the same claim more clearly','Count how many people reposted it'],1,'An independently checked original source gives evidence that a confident answer alone cannot provide.'),
 Q('D04','S02','You want to verify a university application deadline. Which source should you check first?',['An undated social post','A comment from last year','A search-result headline alone','The current official admissions page'],3,'The current official admissions page is the relevant primary source. Check the date and whether it applies to your programme.'),
 Q('D05','S03','An unexpected email says your account closes in ten minutes unless you enter your password. What should you do?',['Use the link quickly','Reply with the password','Open the service through a known address and check independently','Forward the link so a friend can enter their password'],2,'Urgency and requests for credentials are warning signs. Check through a known, independent route rather than the message link.'),
 Q('D06','S03','A message uses a familiar logo. What does that establish?',['The sender is verified','The website is safe','The message cannot be phishing','Nothing by itself; logos can be copied'],3,'A familiar logo does not verify the sender. Check the actual address and the request through a trusted route.'),
 Q('D07','S04','Which formula adds the values in cells B2 through B5?',['=SUM(B2:B5)','=SUM(B2;B5)','=B2:B5','=COUNT(B2:B5)'],0,'SUM(B2:B5) adds the values across the complete B2-to-B5 range.'),
 Q('D08','S04','A total looks too small after you add a new row. What should you check first?',['Change the font size','Whether the formula range includes the new row','Delete the formula','Sort the sheet by colour'],1,'A formula may still refer to the old range. Check its cell references against the rows that should be included.')
];
const PRACTICE={
 S01:[Q('P01','S01','In https://library.example.org/help, which part identifies the registered domain?',['library','help','example.org','https'],2,'The registered domain is example.org; library is the subdomain.'),Q('P02','S01','Does a padlock alone prove that a website belongs to your university?',['Yes, it verifies every organisation','No, encryption does not verify the claimed university affiliation','Only when the page uses its logo','Yes, if the page loads quickly'],1,'A secure connection does not establish that the site belongs to the organisation it claims to represent.')],
 S02:[Q('P03','S02','Two sources disagree about a deadline. What should you compare?',['Their colours','Their follower counts only','Their dates, scope, authors, and original evidence','Which one is shorter'],2,'Dates, applicability, authority, and original evidence help explain why the sources differ.'),Q('P04','S02','A quote links to a report, but the report does not support the claim. What should you conclude?',['A link guarantees the claim is correct','The claim is not supported by that citation','The longer text is always right','The quote should be shared without checking'],1,'A citation is useful only if its source actually supports the claim being made.')],
 S03:[Q('P05','S03','A “student support” message asks you to send a one-time login code. What is the safer response?',['Send it to avoid losing access','Verify the request through the official support channel and keep the code private','Send half the code first','Post the code in a class chat'],1,'A one-time code can grant account access. Keep it private and verify suspicious requests independently.'),Q('P06','S03','The message link is campus-help.example.net, while your university uses example.edu. What should you do?',['Trust the word campus','Open the link and enter credentials','Use the known university address to check the request','Assume both addresses have the same owner'],2,'Different registered domains can have different owners. Check through the known university address.')],
 S04:[Q('P07','S04','B2, B3, and B4 contain 10, 20, and 30. What does =SUM(B2:B4) return?',['3','30','50','60'],3,'The range includes all three values, so the result is 10 + 20 + 30 = 60.'),Q('P08','S04','A new expense is entered in B6, but the total uses =SUM(B2:B5). What should change?',['Extend the range to B2:B6','Rename the worksheet only','Replace SUM with COUNT','Nothing; every formula automatically includes the new cell'],0,'The specified range stops at B5. Extending it to B6 includes the new expense.')]
};
const LESSONS={
 S01:[['Read the address, not just the page','A page title and logo can say anything. In https://portal.example.edu/courses, the registered domain is example.edu, the subdomain is portal, and the path is /courses.'],['Look for the actual domain','In university-login.example.net, the word university-login is a subdomain. It does not show that a university controls the website. Compare the address with a trusted address you already know.'],['Check before you act','Use a saved bookmark or a known official address when signing in. A secure connection protects the connection; it does not by itself establish that a website belongs to the organisation it claims.']],
 S02:[['Start with the specific claim','Identify exactly what is being claimed. A broad headline may omit a date, place, programme, or condition that changes its meaning.'],['Follow the evidence','Look for the original announcement, report, or data. Check who published it, when it was published, and whether the evidence supports the claim. AI-generated answers and search summaries are starting points to check, not evidence by themselves.'],['Compare scope and dates','Two statements may describe different years or groups. Compare the original sources before treating them as a contradiction. If evidence is missing, record uncertainty rather than guessing.']],
 S03:[['Pause when a message creates urgency','An unexpected threat, reward, or request for credentials is a reason to stop and check. A copied logo and a familiar display name do not verify the sender.'],['Check the address and the request','Compare the actual domain with a known address. Ask whether the requested action makes sense. Keep passwords and one-time codes private.'],['Use an independent route','Open the service from a trusted bookmark or contact support through a known channel. You can check the request without using the suspicious link.']],
 S04:[['Define the values you want to add','Identify the first and last cells in your intended range. For example, B2 through B5 is written as B2:B5.'],['Use the formula','Enter =SUM(B2:B5) to add that range. Check that the selected cells contain the values you expect. COUNT answers a different question: how many numeric entries are present.'],['Verify the result','Compare a small example by hand. If you add another value in B6, check whether your formula now includes B6 rather than assuming the range expanded.']]
};
const PATHS={home:'M3 10l9-7 9 7M5 9v11h5v-6h4v6h5V9',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zM13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2',chart:'M4 20V4M4 20h17M8 16v-5M13 16V7M18 16v-8',arrow:'M4 12h15M14 6l6 6-6 6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',check:'M5 12l4 4L19 6',globe:'M3 12h18M12 3c6 5 6 13 0 18M12 3c-6 5-6 13 0 18M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',search:'M21 21l-6-6M17 9a8 8 0 1 1-16 0 8 8 0 0 1 16 0',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',settings:'M4 7h16M4 17h16M8 4v6M16 14v6'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${PATHS[name]||PATHS.book}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const skill=id=>SKILLS.find(s=>s.id===id);const clone=x=>JSON.parse(JSON.stringify(x));const btn=(label,action,id='',type='')=>`<button type="button" class="btn ${type}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const evidence=(c,n)=>({correct:c,total:n,date:'Sample diagnostic',attempt:'sample-diagnostic'});
function fresh(mode='sample'){
 let e={};if(mode==='sample')e={S01:evidence(2,2),S02:evidence(1,2),S03:evidence(0,2),S04:evidence(1,2)};
 if(mode==='met')e=Object.fromEntries(SKILLS.map(s=>[s.id,evidence(2,2)]));
 if(mode==='blocked')e={S02:evidence(2,2),S03:evidence(0,2),S04:evidence(2,2)};
 return {view:'overview',mode,evidence:e,catalog:clone(CATALOG),completed:[],history:[],quiz:null,lastResult:null,activeActivity:'A03',adminEdit:'A03',filter:'all',signedIn:true};
}
let state;try{state=JSON.parse(sessionStorage.getItem('oiqyn-prototype-v1'))}catch{}if(!state||!state.catalog||!state.evidence)state=fresh();
const save=()=>{try{sessionStorage.setItem('oiqyn-prototype-v1',JSON.stringify(state))}catch{}};
function status(id){const e=state.evidence[id];return !e||e.total<2?'unknown':e.correct/e.total>=.7?'met':'needs'}
const STATUS={met:'Target met',needs:'Needs practice',unknown:'Insufficient evidence'};
const chip=id=>`<span class="status ${status(id)}">${STATUS[status(id)]}</span>`;
function blocked(a){return a.prereq.filter(id=>status(id)!=='met')}
function recommend(){
 const candidates=state.catalog.filter(a=>a.status==='Published'&&status(a.skill)==='needs'&&!blocked(a).length).map(a=>{const e=state.evidence[a.skill],p=e.correct/e.total,d=a.difficulty===(p<.35?1:2)?1:0,n=state.completed.includes(a.id)?0:1;return {...a,score:70-100*p+20*d+10*n,d,n}}).sort((a,b)=>b.score-a.score||a.order-b.order||a.id.localeCompare(b.id));
 if(candidates.length)return {type:'recommended',activity:candidates[0]};
 if(SKILLS.some(s=>status(s.id)==='needs'))return {type:'blocked'};
 if(SKILLS.some(s=>status(s.id)==='unknown'))return {type:'unknown'};return {type:'met'};
}
function reason(a){const e=state.evidence[a.skill];return `Your latest qualifying result for ${skill(a.skill).name.toLowerCase()} was <b>${e.correct}/${e.total}</b>. ${a.d?'This activity matches the suggested practice level. ':'This activity targets that practice need. '}${a.prereq.length?'Your prerequisite skills are at target. ':''}${state.completed.includes(a.id)?'You can review it and try the practice again.':'You have not completed this activity yet.'}`}
function go(view){if(!state.signedIn&&view!=='welcome'){view='welcome';toast('Continue with the sample account to enter the learner preview.')}state.view=view;save();render();document.querySelector('h1')?.focus({preventScroll:true});window.scrollTo(0,0)}
let toastTimer;function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500)}
function shell(content){let active=state.view;if(['assessment','results'].includes(active))active='skills';if(active==='activity')active='practice';
const nav=[['overview','home','Overview'],['skills','grid','My skills'],['practice','book','Practice'],['progress','chart','Progress']];
return `<div class="demo"><div><strong>Interactive prototype</strong> <span aria-hidden="true"> · </span> Sample data only</div><div class="demo-controls"><button data-action="new">New learner journey</button><label>Preview <select id="scenario" aria-label="Preview a demonstration scenario"><option value="sample" ${state.mode==='sample'?'selected':''}>Sample profile</option><option value="new" ${state.mode==='new'?'selected':''}>Missing evidence</option><option value="blocked" ${state.mode==='blocked'?'selected':''}>Blocked prerequisite</option><option value="met" ${state.mode==='met'?'selected':''}>All targets met</option></select></label><button data-action="admin">${state.view==='admin'?'Learner view':'Content admin preview'}</button></div></div>
<aside class="sidebar"><div class="brand"><span class="mark">o</span>oiqyn</div><div class="brand-sub">Learn with direction</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,i,title])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${title}${id==='skills'?'<span class="count">4</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-note"><b>Your pace. Your next step.</b>Practice is guided by your assessment evidence, whatever your year of study.</div><div class="person"><span class="avatar">AL</span><div>Alex, demo learner<small>University student · 18+</small><button class="text-btn" data-action="signout">Sign out of demo</button></div></div></div></aside>
<main id="main"><div class="main-inner"><div class="topline"><div class="crumb">Learning workspace <span aria-hidden="true"> / </span> ${state.view==='admin'?'Content preview':nav.find(n=>n[0]===active)?.[2]||'Welcome'}</div><span class="badge"><span class="dot"></span> Pre-defense prototype</span></div>${content}<div class="footer-strip">${icon('info')}<span>This prototype uses sample content and browser-session data. “Target met” refers only to the assessed skills.</span></div></div></main>`}
function head(eyebrow,title,desc=''){return `<header class="page-head"><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1">${title}</h1>${desc?`<p class="intro">${desc}</p>`:''}</header>`}
function skillCard(s){const e=state.evidence[s.id];return `<article class="skill-card"><div class="skill-icon">${icon(s.icon)}</div><h3>${s.name}</h3>${chip(s.id)}<div class="skill-score"><b>${e?Math.round(e.correct/e.total*100)+'%':'—'}</b><small>${e?e.correct+'/'+e.total+' correct':'No qualifying result'}</small></div><div class="progress-track"><div style="width:${e?100*e.correct/e.total:0}%"></div></div><div class="skill-footer">${e?esc(e.date):'Complete assessment to begin'}</div></article>`}
function nextCard(){const r=recommend();if(r.type==='recommended'){const a=r.activity;return `<article class="recommendation"><div class="eyebrow">${icon('shield')} Your next recommended activity</div><div class="rec-layout"><div><h2>${esc(a.title)}</h2><div class="meta"><span>${skill(a.skill).area}</span><span class="sep">/</span><span>${a.minutes} min</span><span class="sep">/</span><span>${a.difficulty===1?'Foundational':'Guided application'}</span></div></div><div class="rec-art"><div class="shield">${icon(skill(a.skill).icon)}</div><span class="floating">✧</span></div></div><div class="reason"><strong>Why this activity?</strong><br>${reason(a)}</div>${btn((state.completed.includes(a.id)?'Review activity':'Start activity')+' '+icon('arrow'),'open',a.id)}</article>`}
const gap=SKILLS.filter(s=>status(s.id)==='needs');const unknown=SKILLS.filter(s=>status(s.id)==='unknown');const map={unknown:['A little evidence comes first.','Complete a short diagnostic to discover where to practise. A skipped question is treated as missing evidence, not a wrong answer.','Start assessment'],met:['You have reached your current targets.','All four represented skills are at target. This describes the assessed content, not a certification of overall digital competence.','View my progress'],blocked:['No suitable activity just yet.',`Practice is needed in ${gap.map(s=>s.name.toLowerCase()).join(', ')}. Current activities are unavailable or their prerequisites are not at target.${unknown.length?' More assessment evidence is needed for '+unknown.map(s=>s.name.toLowerCase()).join(', ')+'.':''}`,'Review my skills']};const [title,desc,label]=map[r.type];return `<article class="recommendation"><div class="eyebrow">Your next step</div><div class="empty">${icon(r.type==='met'?'check':'info')}<h2>${title}</h2><p>${desc}</p>${btn(label,r.type==='unknown'?'diagnostic':'nav',r.type==='met'?'progress':'skills')}</div></article>`}
function overview(){const met=SKILLS.filter(s=>status(s.id)==='met').length,known=SKILLS.filter(s=>status(s.id)!=='unknown').length;return head('Your learning, in focus','Good to see you, Alex.','Build the digital skills you need, one purposeful step at a time.')+`<div class="hero-grid">${nextCard()}<aside class="summary"><div class="eyebrow">Your skill snapshot</div><div class="number">${met}<small> / 4 at target</small></div><div class="progress-track"><div style="width:${met*25}%"></div></div><p>Based on your latest qualifying result for each skill.</p><dl><div><dt>Skills with enough evidence</dt><dd>${known} of 4</dd></div><div><dt>Activities completed</dt><dd>${state.completed.length}</dd></div><div><dt>New attempts in this demo</dt><dd>${state.history.length}</dd></div></dl><button class="text-btn" data-action="nav" data-id="progress">View learning history ${icon('arrow')}</button></aside></div><div class="row section-head"><h2>Your skills</h2><button class="text-btn" data-action="diagnostic">Retake diagnostic ${icon('arrow')}</button></div><div class="skill-grid">${SKILLS.map(skillCard).join('')}</div>`}
function skillsView(){return head('Evidence before assumptions','Your skill profile','Each status uses the latest assessment with at least two scored answers for that skill. Skipped answers do not count as incorrect.')+`<div class="skill-grid">${SKILLS.map(skillCard).join('')}</div><div class="split" style="margin-top:25px"><div class="card"><h2>How to read your profile</h2><ul class="note-list"><li><b>Target met:</b> a qualifying result of at least 70%.</li><li><b>Needs practice:</b> a qualifying result below 70%.</li><li><b>Insufficient evidence:</b> no result with at least two scored answers.</li><li>Completing a lesson and demonstrating a skill are recorded separately.</li></ul><p class="small-text muted">These are proposed prototype settings, not validated competence measures.</p></div><div class="card"><h3>Take another look</h3><p class="intro small-text">A new qualifying assessment can update your next step. A partial result preserves earlier qualifying evidence.</p><div style="margin-top:20px">${btn('Start diagnostic '+icon('arrow'),'diagnostic')}</div></div></div>`}
function startQuiz(activity=null){const a=state.catalog.find(x=>x.id===activity);if(a&&(a.status!=='Published'||blocked(a).length)){toast('This activity is unavailable or its prerequisites are not at target.');return}state.quiz={activity:activity,questions:clone(a?PRACTICE[a.skill]:DIAGNOSTIC),answers:Array(a?2:8).fill(null),index:0};go('assessment')}
function assessment(){const qz=state.quiz;if(!qz)return overview();const q=qz.questions[qz.index];return head(qz.activity?'Activity practice':'Initial diagnostic',qz.activity?'Put your learning into practice.':'Find your starting point.','Answer what you can. You can skip any question; missing evidence will stay visible.')+`<div class="split"><section class="card assessment-card"><div class="row small-text muted"><span>Question ${qz.index+1} of ${qz.questions.length}</span><span>${qz.activity?'Practice assessment':'Four skill areas'}</span></div><div class="step-dots" aria-hidden="true">${qz.questions.map((_,i)=>`<span class="${i<qz.index?'done':i===qz.index?'current':''}"></span>`).join('')}</div><div class="question-meta">${skill(q.skill).area}</div><h2 class="question-title" id="question-title">${esc(q.prompt)}</h2><div class="options" role="radiogroup" aria-labelledby="question-title">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${qz.answers[qz.index]===i?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div><div class="error" id="quiz-error" role="alert"></div><div class="question-actions"><button class="text-btn" data-action="skip">Skip this question</button><div class="actions">${qz.index?btn('Back','back-question','','secondary'):''}${btn(qz.index===qz.questions.length-1?'Finish assessment':'Next question '+icon('arrow'),'next-question')}</div></div></section><aside class="card"><h3>A useful starting point</h3><ol class="step-list"><li><span class="step-number">1</span>Answer a few short questions</li><li><span class="step-number">2</span>See what the evidence shows</li><li><span class="step-number">3</span>Get a suitable next activity</li></ol><div class="soft info" style="margin-top:25px">You are not expected to know everything. Skipping is more useful than pretending to be certain.</div></aside></div>`}
function renderQuestion(){save();render();const q=document.getElementById('question-title');q?.setAttribute('tabindex','-1');q?.focus({preventScroll:true});document.querySelector('.assessment-card')?.scrollIntoView({block:'start'});}
function submitQuiz(){const qz=state.quiz;if(!qz)return;const id='demo-'+Date.now();let total=0,correct=0;const per={};qz.questions.forEach((q,i)=>{per[q.skill]??={correct:0,total:0};if(qz.answers[i]!==null){total++;per[q.skill].total++;if(qz.answers[i]===q.correct){correct++;per[q.skill].correct++}}});Object.entries(per).forEach(([k,v])=>{if(v.total>=2)state.evidence[k]={...v,date:'Latest demo attempt',attempt:id}});const result={id,activity:qz.activity,title:qz.activity?state.catalog.find(a=>a.id===qz.activity).title:'Diagnostic assessment',correct,total,questions:qz.questions,answers:qz.answers,date:'This demo session'};state.history.unshift(result);state.lastResult=result;state.quiz=null;go('results')}
function results(){const r=state.lastResult;if(!r)return overview();return head('Assessment feedback','A clearer picture of your skills.','Your scored answers update the profile only when there is enough evidence for that skill.')+`<div class="split"><div class="feedback-list">${r.questions.map((q,i)=>{const answer=r.answers[i],kind=answer===null?'unknown':answer===q.correct?'met':'needs';return `<article class="feedback-item"><span class="status ${kind}">${answer===null?'Skipped · no scored evidence':answer===q.correct?'Correct':'Needs another look'}</span><h3>${esc(q.prompt)}</h3><div class="answer">${answer===null?'No answer submitted.':'Your answer: '+esc(q.options[answer])}</div><p><b>Explanation:</b> ${esc(q.why)}</p></article>`}).join('')}</div><aside class="stack" style="align-content:start"><div class="card"><div class="eyebrow">This attempt</div><div class="result-big">${r.total?Math.round(100*r.correct/r.total)+'%':'—'}</div><p class="muted small-text">${r.total?r.correct+' of '+r.total+' scored answers correct.':'Insufficient evidence. No answers were scored.'} ${r.questions.length-r.total} skipped.</p><div style="margin-top:22px">${btn('See my next step '+icon('arrow'),'nav','overview','wide')}</div></div><div class="soft">An attempt percentage is not a complete skill profile. Skills with fewer than two scored responses keep their previous qualifying result, or stay “Insufficient evidence”.</div></aside></div>`}
function practice(){return head('A small step makes a difference','Your practice library','Short activities across four digital skill areas. Prerequisites are checked before an activity can be opened.')+`<div class="activity-list">${state.catalog.filter(a=>a.status==='Published').map(a=>{const b=blocked(a);return `<article class="activity-card"><div class="eyebrow">${skill(a.skill).area}</div><h3>${esc(a.title)}</h3><p>${esc(a.objective)}</p><div class="meta"><span>${a.minutes} min</span><span class="sep">/</span><span>${a.difficulty===1?'Foundational':'Guided application'}</span></div>${b.length?`<div class="soft warning small-text">Prerequisite needed: ${b.map(id=>skill(id).name+' ('+STATUS[status(id)]+')').join(', ')}.</div>`:''}<div class="row"><span class="status ${state.completed.includes(a.id)?'met':''}">${state.completed.includes(a.id)?'Lesson completed':'Ready when you are'}</span><button class="btn small secondary" data-action="open" data-id="${a.id}" ${b.length?'disabled':''}>${state.completed.includes(a.id)?'Review':'Open activity'} ${icon('arrow')}</button></div></article>`}).join('')||'<div class="card"><h2>No activities are published.</h2><p class="intro">Your evidence is retained. Published learning materials will appear here when available.</p></div>'}</div>`}
function activityView(){const a=state.catalog.find(a=>a.id===state.activeActivity);if(!a||a.status!=='Published'||blocked(a).length)return head('Availability updated','This activity is not available right now.','Its publication status or prerequisites have changed.')+btn('Get my next step','nav','overview');const done=state.completed.includes(a.id);return head(skill(a.skill).area,esc(a.title),esc(a.objective))+`<div class="split"><article class="card lesson-content">${LESSONS[a.skill].map(([t,p],i)=>`<h2>${i+1}. ${t}</h2><p>${esc(p)}</p>${a.skill==='S03'&&i===1?'<div class="message-example"><div class="mail-head">Illustrative message · fictional addresses</div><strong>Action required: verify your student account</strong><p>“Your access will end today. Sign in immediately to keep your account.”</p><p><code>campus-help.example.net/verify</code></p></div>':''}`).join('')}<div class="soft" style="margin-top:23px"><b>Pause and reflect</b><p>${a.skill==='S03'?'What would you check before responding to this message? Choose a route that does not depend on the message itself.':'Think of a recent task where this skill would have helped. What would you check first?'}</p></div></article><aside class="stack" style="align-content:start"><div class="card"><div class="eyebrow">Your activity</div><h3>${a.minutes} minutes of focused practice</h3><div class="meta"><span>${a.difficulty===1?'Foundational practice':'Guided application'}</span></div>${chip(a.skill)}<div class="completion-row">${icon(done?'check':'book')}<span>${done?'Lesson marked complete':'Lesson completion not recorded'}</span></div><div class="stack" style="margin-top:18px">${btn(done?'Lesson completed':'Mark lesson complete','complete',a.id,done?'secondary':'secondary')}${btn('Start practice '+icon('arrow'),'practice-quiz',a.id)}</div></div><div class="soft info">Finishing the lesson records completion. A qualifying practice result is what updates your assessed skill.</div></aside></div>`}
function progress(){const entries=state.history.filter(r=>state.filter==='all'||r.questions.some(q=>q.skill===state.filter));return head('Your progress, with evidence','See how your next step changes.','Keep lesson completion and assessed results in view. This demo history belongs only to the current browser session.')+`<div class="hero-banner">${icon('chart')}<div><h3>${state.completed.length} activities completed · ${SKILLS.filter(s=>status(s.id)==='met').length} skills at target</h3><p>Completing an activity does not automatically establish a skill.</p></div></div><div class="card"><div class="row"><h2>Assessment history</h2><label class="field" style="margin:0">Filter by skill<select id="history-filter"><option value="all">All skills</option>${SKILLS.map(s=>`<option value="${s.id}" ${state.filter===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Assessment</th><th>Result</th><th>Scored / skipped</th><th>Evidence</th><th></th></tr></thead><tbody>${entries.map(r=>`<tr><td>${esc(r.title)}</td><td>${r.total?Math.round(100*r.correct/r.total)+'%':'No score'}</td><td>${r.total} / ${r.questions.length-r.total}</td><td>${r.date}</td><td><button class="text-btn" data-action="show-result" data-id="${r.id}">Review</button></td></tr>`).join('')||'<tr><td colspan="5">No new attempts match this view. Complete a diagnostic or activity assessment to add one.</td></tr>'}</tbody></table></div></div><div class="split" style="margin-top:22px"><div class="card"><h2>Completed activities</h2>${state.completed.map(id=>`<div class="completion-row">${icon('check')}<span>${esc(state.catalog.find(a=>a.id===id)?.title||id)}</span></div>`).join('')||'<p class="intro small-text">Completed lessons will appear here.</p>'}</div><div class="card"><h3>About the sample profile</h3><p class="intro small-text">Sample scenario evidence is preloaded for demonstration. It is not a participant result and is not listed as a new attempt.</p></div></div>`}
function welcome(){return `<div class="login-layout"><section class="login-hero"><div class="eyebrow">IT & digital literacy</div><h1 tabindex="-1">A clearer path.<br><span>Your next step.</span></h1><p class="intro">Find what you already know. Practise what needs attention. Understand why each activity is recommended.</p><div class="login-points"><div class="login-point">${icon('grid')}A short, skill-based diagnostic</div><div class="login-point">${icon('shield')}Activities matched to your evidence</div><div class="login-point">${icon('chart')}Progress you can understand</div></div></section><section class="card login-card"><h2>${state.authMode==='register'?'Create your learning profile':'Welcome to Oiqyn'}</h2><p class="muted small-text">For adult university students, across every year of study.</p><div class="field"><label for="demo-email">Email</label><input id="demo-email" type="email" value="alex.student@example.com" readonly aria-describedby="demo-account-note"></div><div class="field"><label for="demo-password">Password</label><input id="demo-password" type="password" value="sample-only" readonly></div><p id="demo-account-note" class="small-text muted" style="margin-bottom:20px">Sample account preview. No real account is created and no credentials are submitted.</p>${btn(state.authMode==='register'?'Create demo profile':'Continue with demo account','enter-demo','','wide')}<div class="row" style="margin-top:19px"><span class="small-text muted">${state.authMode==='register'?'Already have an account?':'New to Oiqyn?'}</span><button class="text-btn" data-action="auth-toggle">${state.authMode==='register'?'Sign-in preview':'Registration preview'}</button></div></section></div>`}
function admin(){const a=state.catalog.find(a=>a.id===state.adminEdit)||state.catalog[0];return head('Content administrator preview','Keep learning content connected.','Review the skill, difficulty, prerequisites, and publication status of each activity.')+`<div class="soft info" style="margin-bottom:22px">Demonstration mode: edits affect this browser session only. Account permissions and server-side validation are part of the planned backend.</div><div class="split"><div class="card"><h2>Activity catalogue</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Activity</th><th>Status</th><th>Version</th><th></th></tr></thead><tbody>${state.catalog.map(c=>`<tr><td><b>${esc(c.title)}</b><br><span class="small-text muted">${c.id} · ${skill(c.skill).name}</span></td><td><span class="status ${c.status==='Published'?'met':''}">${c.status}</span></td><td>v${c.version}</td><td><button class="text-btn" data-action="edit" data-id="${c.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></div><aside class="card"><div class="eyebrow">${a.id} · content editor</div><h2>Edit activity</h2><form id="editor" style="margin-top:20px"><label class="field">Title<input name="title" value="${esc(a.title)}" maxlength="90" required></label><label class="field">Primary skill<select name="skill">${SKILLS.map(s=>`<option value="${s.id}" ${a.skill===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label class="field">Difficulty<select name="difficulty"><option value="1" ${a.difficulty===1?'selected':''}>1 — Foundational</option><option value="2" ${a.difficulty===2?'selected':''}>2 — Guided application</option></select></label><div class="field">Prerequisite skills<div class="check-grid">${SKILLS.map(s=>`<label><input type="checkbox" name="prereq" value="${s.id}" ${a.prereq.includes(s.id)?'checked':''}>${s.name}</label>`).join('')}</div></div><div class="soft small-text">Sample content contains a lesson and two practice questions for each target skill. Full question authoring is outside this prototype.</div><div class="error" id="editor-error" role="alert"></div><div class="editor-actions actions"><button type="submit" class="btn small">Save & publish</button>${btn(a.status==='Archived'?'Keep archived':'Archive','archive',a.id,'small secondary')}</div></form></aside></div>`}
function render(){const views={overview,skills:skillsView,assessment,results,practice,activity:activityView,progress,welcome,admin};document.getElementById('app').innerHTML=shell((views[state.view]||overview)());document.title='Oiqyn — '+(state.view==='overview'?'Your next learning step':state.view.charAt(0).toUpperCase()+state.view.slice(1));}
document.addEventListener('change',e=>{if(e.target.name==='answer'&&state.quiz){state.quiz.answers[state.quiz.index]=Number(e.target.value);save();document.getElementById('quiz-error').textContent=''}if(e.target.id==='scenario'){state=fresh(e.target.value);save();render();toast('Demonstration scenario loaded.')}if(e.target.id==='history-filter'){state.filter=e.target.value;save();render()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
 case 'nav':go(id);break;
 case 'new':state=fresh('new');state.authMode='register';state.signedIn=false;go('welcome');break;
 case 'signout':state.signedIn=false;state.authMode='login';go('welcome');toast('Demo session signed out. Sample data is retained for the preview.');break;
 case 'auth-toggle':state.authMode=state.authMode==='register'?'login':'register';save();render();break;
 case 'enter-demo':state.signedIn=true;if(SKILLS.every(s=>status(s.id)==='unknown'))startQuiz();else go('overview');break;
 case 'admin':state.signedIn=true;go(state.view==='admin'?'overview':'admin');break;
 case 'diagnostic':startQuiz();break;
 case 'practice-quiz':startQuiz(id);break;
 case 'open':{const item=state.catalog.find(a=>a.id===id);if(!item||item.status!=='Published'||blocked(item).length){toast('This activity is not available. Review its prerequisites.');break;}state.activeActivity=id;go('activity');break;}
 case 'complete':if(!state.completed.includes(id)){state.completed.push(id);save();render();toast('Lesson completed. Your assessed skill has not changed.')}else toast('This lesson is already marked complete.');break;
 case 'skip':state.quiz.answers[state.quiz.index]=null;if(state.quiz.index===state.quiz.questions.length-1)submitQuiz();else{state.quiz.index++;renderQuestion()}break;
 case 'next-question':if(state.quiz.answers[state.quiz.index]===null){document.getElementById('quiz-error').textContent='Choose an answer, or use “Skip this question”.';break}if(state.quiz.index===state.quiz.questions.length-1)submitQuiz();else{state.quiz.index++;renderQuestion()}break;
 case 'back-question':state.quiz.index--;renderQuestion();break;
 case 'show-result':state.lastResult=state.history.find(r=>r.id===id);go('results');break;
 case 'edit':state.adminEdit=id;save();render();break;
 case 'archive':{const item=state.catalog.find(a=>a.id===id);item.status='Archived';save();render();toast('Activity archived in this preview. New recommendations exclude it.');break;}
}});
function hasCycle(items){const g=Object.fromEntries(SKILLS.map(s=>[s.id,[]]));items.filter(a=>a.status==='Published').forEach(a=>a.prereq.forEach(p=>g[p].push(a.skill)));const visiting=new Set(),done=new Set();function visit(v){if(visiting.has(v))return true;if(done.has(v))return false;visiting.add(v);for(const w of g[v])if(visit(w))return true;visiting.delete(v);done.add(v);return false}return SKILLS.some(s=>visit(s.id))}
document.addEventListener('submit',e=>{if(e.target.id!=='editor')return;e.preventDefault();const form=new FormData(e.target),old=state.catalog.find(a=>a.id===state.adminEdit);const item={...old,title:String(form.get('title')).trim(),skill:String(form.get('skill')),difficulty:Number(form.get('difficulty')),prereq:form.getAll('prereq'),status:'Published',version:old.version+1};let err='';if(!item.title)err='Add a title before publishing.';else if(item.prereq.includes(item.skill))err='A skill cannot be its own prerequisite.';else if(hasCycle(state.catalog.map(a=>a.id===item.id?item:a)))err='These prerequisite links create a cycle. Revise them before publishing.';if(err){document.getElementById('editor-error').textContent=err;return}state.catalog=state.catalog.map(a=>a.id===item.id?item:a);save();render();toast('A new sample version was published. Existing assessment feedback remains unchanged.');});
render();
